// ---- quotes (creator_quote) ------------------------------------------------
// `?creator_id=` opens one creator's offers, `?status=` one segment of the quote
// ledger. The read order is the offer's own date, falling back to when the row
// was typed so a draft (no `quoted_at` yet) does not sort below an older sent
// quote.
func (q *Queries) ListCreatorQuotes(ctx context.Context, arg ListCreatorQuotesParams) ([]CreatorQuote, error) {
	rows, err := q.db.Query(ctx, listCreatorQuotes,
		arg.WorkspaceID,
		arg.CreatorID,
		arg.Status,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CreatorQuote{}
	for rows.Next() {
		var i CreatorQuote
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.CreatorID,
			&i.BriefID,
			&i.Status,
			&i.QuotedAt,
			&i.ValidUntil,
			&i.FeeAmount,
			&i.CommissionRate,
			&i.Currency,
			&i.Items,
			&i.Note,
			&i.OwnerMemberID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

